public class Inheritance {
    static class Animal {
        String sound() { return "..."; }
    }
    static class Dog extends Animal {
        @Override String sound() { return "Woof"; }
    }
    public static void main(String[] args) {
        Animal a = new Dog();
        System.out.println(a.sound() + " " + new Animal().sound());
    }
}
